from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    # pattern "0110"
    pattern = [0, 1, 1, 0]  # bit values at positions 0..3

    # ----- Phase 1: compute per‑offset matches into ancillas 0..4 -----
    for offset in range(5):
        # apply X on problem qubits where pattern bit is 0
        for i in range(4):
            if pattern[i] == 0:
                qc.x(problem_qubits[offset + i])
        # controlled X: set ancilla[offset] to 1 iff substring matches pattern
        controls = [problem_qubits[offset + i] for i in range(4)]
        qc.mcx(controls, ancilla_qubits[offset])
        # undo the X gates
        for i in range(4):
            if pattern[i] == 0:
                qc.x(problem_qubits[offset + i])

    # ----- Phase 2: compute OR of all matches into ancilla[5] -----
    # flip all per‑offset flags
    for off in range(5):
        qc.x(ancilla_qubits[off])
    # 5‑controlled X: ancilla[5] becomes 1 iff all flipped flags are 1
    qc.mcx(ancilla_qubits[:5], ancilla_qubits[5])
    # flip OR ancilla: now 1 iff any original match was 1
    qc.x(ancilla_qubits[5])
    # restore per‑offset flags
    for off in range(5):
        qc.x(ancilla_qubits[off])

    # ----- Phase 3: apply the phase flip -----
    qc.z(ancilla_qubits[5])

    # ----- Phase 4: uncompute OR (reverse of phase 2) -----
    for off in range(5):
        qc.x(ancilla_qubits[off])
    qc.mcx(ancilla_qubits[:5], ancilla_qubits[5])
